L = ['en', 'es', 'pt', 'fr', 'de', 'ja', 'ko', 'zh']
if __name__ == '__main__':
    import json, os, re
    here = os.path.dirname(os.path.abspath(__file__)); root = os.path.dirname(here)
    D = {l: {} for l in L}
    s = open(os.path.join(root, 'i18n.js'), encoding='utf-8').read(); app = json.loads(s[s.index('{'):s.rindex('}') + 1])
    for k in REUSE:
        for l in L: D[l][k] = app[l][k]          # KeyError = the gear's name is missing in tools/i18n_src.py
    seen = set()
    for r in ROWS:
        assert r[0] not in seen, 'twice: ' + r[0]; seen.add(r[0])
        ph = sorted(re.findall(r'\{\w+\}', r[0]))
        for l, v in zip(L, r[1:]):
            assert sorted(re.findall(r'\{\w+\}', v)) == ph, (l, r[0], v)                 # same {placeholders}
            assert v.count('<b>') == r[0].count('<b>') == v.count('</b>'), (l, r[0], v)  # same <b> tags
            assert not re.search('[А-Яа-яЁё]', v), (l, v)
            D[l][r[0]] = v
    out = ('// Translations of the 3D city — generated by tools/i18n_city3d.py (edit there, then: python3 tools/i18n_city3d.py).\n'
           '// Key = the Russian text in the code (_t), value = the text in the app\'s language.\n'
           'window.I18N3 = {\n' + ',\n'.join(' ' + json.dumps(l) + ': ' + json.dumps(D[l], ensure_ascii=False, separators=(',', ':')) for l in L) + '\n};\n')
    open(os.path.join(root, 'city3d-i18n.js'), 'w', encoding='utf-8').write(out)
    print(len(ROWS) + len(REUSE), 'keys ×', len(L), 'languages →', round(len(out.encode()) / 1024), 'KB')
